#include <stdio.h>

void print_roman(int n) {
    int values[] = {10, 9, 5, 4, 1};
    const char *symbols[] = {"X", "IX", "V", "IV", "I"};
    for (int i = 0; i < 5; i++) {
        while (n >= values[i]) {
            printf("%s", symbols[i]);
            n -= values[i];
        }
    }
    printf("\n");
}

int main() {
    print_roman(14);
    print_roman(6);
    return 0;
}
